const allItems = $input.all();

let hotNews = [];
let techNews = [];

for (const item of allItems) {
  const j = item.json;
  // RSS items have a "title" and "link" field
  if (j.title && j.link) {
    hotNews.push({
      title: j.title,
      url: j.link,
      source: "36氪"
    });
  }
  // HN items have a "hits" array
  if (j.hits) {
    const hits = j.hits || [];
    techNews = hits.slice(0, 5).map(hit => ({
      title: hit.title || "(no title)",
      url: hit.url || ("https://news.ycombinator.com/item?id=" + hit.objectID),
      source: "Hacker News",
      score: hit.points || 0
    }));
  }
}

hotNews = hotNews.slice(0, 5);

return [{ json: { hotNews, techNews, aiSummary: null, generatedAt: new Date().toISOString() } }];

const items = [];
const input = $input.first().json;
const today = new Date().toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' });

let summary = '📰 每日新闻概要 | ' + today + '\n\n';

summary += '🔥 热点新闻 (' + (input.hotNews || []).length + '条):\n';
(input.hotNews || []).forEach((n, i) => {
  summary += (i + 1) + '. ' + (n.title || '').substring(0, 80) + '\n';
});

summary += '\n💻 科技新闻 (' + (input.techNews || []).length + '条):\n';
(input.techNews || []).forEach((n, i) => {
  summary += (i + 1) + '. ' + (n.title || '').substring(0, 80);
  if (n.score) summary += ' (⬆' + n.score + ')';
  summary += '\n';
});

summary += '\n📌 来源: 36氪 + Hacker News | 🤖 自动生成';

for (const news of input.hotNews || []) {
  items.push({
    json: {
      fields: {
        "文本": news.title || '',
        "原文链接": news.url || '',
        "来源": news.source || '36氪',
        "分类": "热点新闻",
        "news_date": new Date(input.generatedAt || Date.now()).getTime(),
        "新闻概要": summary
      }
    }
  });
}

for (const news of input.techNews || []) {
  items.push({
    json: {
      fields: {
        "文本": news.title || '',
        "原文链接": news.url || '',
        "来源": news.source || 'Hacker News',
        "分类": "科技新闻",
        "news_date": new Date(input.generatedAt || Date.now()).getTime(),
        "新闻概要": summary
      }
    }
  });
}

// Wrap into batch format
const records = items.map(item => ({ fields: item.json.fields }));
return [{ json: { records: JSON.stringify({ records }) } }];

const input = $input.first().json;
const today = new Date().toLocaleDateString('zh-CN', {
  year: 'numeric', month: 'long', day: 'numeric', weekday: 'long'
});

let hotNewsText = '';
for (let i = 0; i < (input.hotNews || []).length; i++) {
  const n = input.hotNews[i];
  hotNewsText += '🔥 ' + (i + 1) + '. [' + n.title + '](' + n.url + ') — ' + n.source + '\n';
}

let techNewsText = '';
for (let i = 0; i < (input.techNews || []).length; i++) {
  const n = input.techNews[i];
  techNewsText += '💻 ' + (i + 1) + '. [' + n.title + '](' + n.url + ') — ' + n.source + '\n';
}

const summaryText = input.aiSummary ? '\n---\n**AI 摘要**\n' + input.aiSummary + '\n' : '';

const elements = [];
const allNews = (input.hotNews || []).concat(input.techNews || []);
for (let i = 0; i < Math.min(allNews.length, 10); i++) {
  const n = allNews[i];
  const category = i < (input.hotNews || []).length ? '🔥 热点' : '💻 科技';
  elements.push({
    tag: 'div',
    fields: [
      {
        text: {
          content: '**' + (i + 1) + '.** [' + (n.title || '').substring(0, 100) + '](' + (n.url || '') + ')',
          tag: 'lark_md'
        },
        is_short: false
      },
      {
        text: {
          content: category + ' | ' + (n.source || '') + (n.score ? ' | ⬆ ' + n.score : ''),
          tag: 'lark_md'
        },
        is_short: true
      }
    ]
  });
}

return [{
  json: {
    msg_type: 'interactive',
    content: JSON.stringify({
      config: { wide_screen_mode: true },
      header: {
        template: 'blue',
        title: { content: '📰 每日新闻速递 — ' + today, tag: 'plain_text' }
      },
      elements: elements,
      note: {
        elements: [{
          tag: 'plain_text',
          content: '🤖 由 Daily News Agent 自动生成 | ' + new Date().toLocaleString('zh-CN')
        }]
      }
    })
  }
}];
